@@ -0,0 +1,50 @@
+// Sales from the till: each dish sold uses one portion of its recipe per
+// `qty`. A ticket is imported once; importing is all or nothing.
+import { AppError } from "../errors.js";
+import { consume } from "./batches.js";
+import { getItem, onHand } from "./items.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+const round3 = (n) => Math.round(n * 1000) / 1000;
+
+/** True when a ticket has already been imported. */
+export function ticketImported(store, ticket) {
+  return (store.data.sales ?? []).some((s) => s.ticket === ticket);
+}
+
+/** Ingredient quantities one sale line used (its recipe, `qty` portions). */
+export function saleUse(store, sale) {
+  return scaled(getRecipe(store, sale.recipeId), sale.qty).filter((n) => n.qty > 0);
+}
+
+/**
+ * Records sale lines [{ row, ticket, soldAt, dishId, qty }] and consumes their
+ * ingredients (ref `sale:<ticket>`). Tickets already imported are skipped.
+ * Checks every line first; throws sale_not_enough_stock naming the row and
+ * changes nothing when an item runs out. Returns { tickets, dishes } counts.
+ */
+export function recordSales(store, lines) {
+  const fresh = lines
+    .filter((l) => !ticketImported(store, l.ticket))
+    .map((l) => ({ ...l, recipeId: getDish(store, l.dishId).recipeId }));
+  const needed = new Map();
+  for (const l of fresh) {
+    for (const n of saleUse(store, l)) {
+      const total = round3((needed.get(n.itemId) ?? 0) + n.qty);
+      const available = round3(onHand(store, n.itemId));
+      if (available < total) {
+        const item = getItem(store, n.itemId);
+        const left = round3(Math.max(0, available - (needed.get(n.itemId) ?? 0)));
+        throw new AppError("sale_not_enough_stock", { row: l.row, available: left, unit: item.unit, item: item.name });
+      }
+      needed.set(n.itemId, total);
+    }
+  }
+  store.data.sales ??= [];
+  for (const l of fresh) {
+    for (const n of saleUse(store, l)) consume(store, n.itemId, n.qty, { at: l.soldAt, ref: `sale:${l.ticket}` });
+    store.data.sales.push({ id: store.nextId("sale"), ticket: l.ticket, soldAt: l.soldAt, dishId: l.dishId, recipeId: l.recipeId, qty: l.qty });
+  }
+  return { tickets: new Set(fresh.map((l) => l.ticket)).size, dishes: fresh.reduce((s, l) => s + l.qty, 0) };
+}
